/* The same selected analysis records appear in planning and exported summaries. */
'use strict';
(()=>{
 const langs=['zh','en','fr','es','eu'],A=()=>window.YV_APP,B=()=>window.YV_BUILDER;
 const words={title:['已选分析与自动关联','Selected analyses and linked methods','Analyses et méthodes associées','Análisis y métodos vinculados','Hautatutako analisiak eta lotutako metodoak'],tools:['工具','Tools','Outils','Herramientas','Tresnak'],inputs:['资料与来源','Inputs and sources','Données et sources','Datos y fuentes','Datuak eta iturriak'],status:['准备状态','Preparation status','État de préparation','Estado de preparación','Prestaketa-egoera'],edit:['调整分析','Adjust analyses','Ajuster les analyses','Ajustar análisis','Egokitu analisiak'],pending:['待准备','Preparation pending','Préparation requise','Preparación pendiente','Prestatzeke'],ready:['条件已记录','Conditions recorded','Conditions consignées','Condiciones registradas','Baldintzak erregistratuta'],model:['模型配置','Model specification','Spécification du modèle','Especificación del modelo','Ereduaren zehaztapena']};
 Object.assign(words,{variant:['方法分支','Method variant','Variante','Variante','Metodo-aldaera'],metrics:['指标','Metrics','Indicateurs','Indicadores','Metrikak'],call:['模型调用','Model call','Appel du modèle','Llamada del modelo','Eredu-deia'],references:['参考来源','References','Références','Referencias','Erreferentziak']});
 const lang=()=>A()?.prefs().language||'en',T=(k,language=lang())=>words[k]?.[Math.max(0,langs.indexOf(language))]||k;
 const tx=(value,language=lang())=>typeof value==='string'?value:value?.[language]||value?.en||'';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const reviews=x=>x?.analysisSelectionRecords?.selections||B()?.analysisReview?.().selections||[];
 function panel(){const rows=reviews();if(!rows.length)return '';return `<section class="panel av30-panel" aria-label="${esc(T('title'))}"><div class="section-head"><h2>${esc(T('title'))}</h2><a href="#projects?view=evolution">${esc(T('edit'))} ↗</a></div><div class="av30-grid">${rows.map(r=>`<article><h3>${esc(tx(r.recipe.title))}</h3><p>${r.toolIds.map(id=>esc(A().maps().tool.get(id)?.name||id)).join(' · ')}</p><small>${esc(T(r.status==='conditions-recorded'?'ready':'pending'))} · ${r.metricIds.length} ${esc(A().t('metrics'))}</small></article>`).join('')}</div></section>`;}
 function tableData(x,language=lang()){return reviews(x).map(r=>[tx(r.recipe.title,language),r.recipe.variantId||'',r.toolIds.map(id=>A().maps().tool.get(id)?.name||id).join('\n'),r.metricIds.join('\n'),r.requiredData.map(id=>window.YV_EXPORT_LAYOUT?.context?.().input(id)||A().data().categories.dataRequirements.find(v=>v.id===id)?.titleEn||id).join('\n'),r.additionalRequirements.map(q=>tx(q.label,language)+': '+(q.sourceRef||T('pending',language))).join('\n'),T(r.status==='conditions-recorded'?'ready':'pending',language),r.recipe.modelSpecification?.expression||'',r.recipe.modelSpecification?.entrypoint||'',(r.recipe.sourceUrls||[]).join('\n')]);}
 function markdown(x,c){const rows=reviews(x);if(!rows.length)return '';const language=c?.language||lang();return `## ${T('title',language)}\n\n`+rows.map(r=>`### ${tx(r.recipe.title,language)}\n\n${r.toolIds.map(id=>A().maps().tool.get(id)?.name||id).join(' · ')}\n\n${r.recipe.modelSpecification?.expression||''}\n\n${r.additionalRequirements.map(q=>'- '+tx(q.label,language)+': '+(q.sourceRef||T('pending',language))).join('\n')}\n`).join('\n')+'\n';}
 function html(x,citations){const rows=reviews(x);if(!rows.length)return '';const language=x.language||lang();return `<section id="selected-analyses"><h2>${esc(T('title',language))}</h2>${rows.map(r=>`<h3>${esc(tx(r.recipe.title,language))}</h3><p>${r.toolIds.map(id=>esc(A().maps().tool.get(id)?.name||id)).join(' · ')}</p>${r.recipe.modelSpecification?.expression?`<p><code>${esc(r.recipe.modelSpecification.expression)}</code></p>`:''}<ul>${r.additionalRequirements.map(q=>`<li>${esc(tx(q.label,language))}: ${esc(q.sourceRef||T('pending',language))}</li>`).join('')}</ul><p>${citations?.cite?.(r.recipe.sourceUrls||[])||''}</p>`).join('')}</section>`;}
 window.YV_ANALYSIS_OVERVIEW={panel,tableData,markdown,html,text:T};
})();
